mapper.select:
SELECT id FROM provider_media_filing
WHERE filing_method = 'API'
  AND next_action IN ('SUBMIT', 'QUERY')
  AND next_action_at <= #{now}
  AND (lease_until IS NULL OR lease_until <= #{now})
ORDER BY next_action_at ASC, id ASC LIMIT #{limit}

mapper.update:
UPDATE provider_media_filing
SET lease_owner = #{owner}, lease_until = #{leaseUntil}
WHERE id = #{id} AND filing_method = #{filingMethod}
  AND next_action = #{expectedAction} AND task_data_version = #{taskDataVersion}
  AND next_action_at <= #{now}
  AND (lease_until IS NULL OR lease_until <= #{now})

UPDATE provider_media_filing
SET last_submit_attempt_at = #{attemptedAt}
WHERE id = #{id} AND lease_owner = #{owner}
  AND filing_method = #{filingMethod} AND next_action = #{expectedAction}
  AND task_data_version = #{taskDataVersion}

UPDATE provider_media_filing
SET status = 'SUBMIT_FAILED', next_action = 'NONE', next_action_at = NULL,
    last_error_code = #{errorCode}, last_error_message = #{errorMessage},
    lease_owner = NULL, lease_until = NULL
WHERE id = #{id} AND lease_owner = #{owner}
  AND filing_method = #{filingMethod} AND next_action = #{expectedAction}
  AND task_data_version = #{taskDataVersion}
  AND submitted_data_version IS NULL

UPDATE provider_media_filing
SET status = 'PENDING', submitted_data_version = #{taskDataVersion}, last_submitted_at = #{submittedAt},
    next_action = 'QUERY', next_action_at = #{nextQueryAt}, retry_count = 0,
    last_error_code = NULL, last_error_message = NULL, lease_owner = NULL, lease_until = NULL
WHERE id = #{id} AND lease_owner = #{owner}
  AND filing_method = #{filingMethod} AND next_action = #{expectedAction}
  AND task_data_version = #{taskDataVersion}

UPDATE provider_media_filing
SET status = #{status}, remote_status = #{remoteStatus}, external_filing_id = #{externalFilingId},
    filing_time = #{filingTime}, operate_time = #{operateTime}, last_queried_at = #{queriedAt},
    next_action = #{nextAction}, next_action_at = #{nextActionAt}, retry_count = 0,
    last_error_code = NULL, last_error_message = NULL, lease_owner = NULL, lease_until = NULL
WHERE id = #{id} AND lease_owner = #{owner}
  AND filing_method = #{filingMethod} AND next_action = #{expectedAction}
  AND task_data_version = #{taskDataVersion}

UPDATE provider_media_filing
SET status = #{status}, next_action = #{nextAction}, next_action_at = #{nextActionAt},
    retry_count = #{retryCount}, last_error_code = #{errorCode},
    last_error_message = #{errorMessage}, lease_owner = NULL, lease_until = NULL
WHERE id = #{id} AND lease_owner = #{owner}
  AND filing_method = #{filingMethod} AND next_action = #{expectedAction}
  AND task_data_version = #{taskDataVersion}
